<template><div class="max-w-6xl mx-auto p-5 sm:p-8"><div class="flex flex-wrap gap-3 justify-between items-end"><div><h1 class="text-2xl font-bold text-white">จัดการไฟล์</h1><nav class="text-sm text-dark-400 mt-2"><button class="hover:text-white" @click="go('')">data</button><template v-for="(part,index) in crumbs" :key="index"><span class="mx-1">/</span><button class="hover:text-white" @click="go(crumbs.slice(0,index+1).join('/'))">{{part}}</button></template></nav></div><div class="flex flex-wrap gap-2"><label class="button secondary cursor-pointer">↑ อัปโหลด<input ref="uploadInput" class="hidden" type="file" multiple @change="upload" /></label><button class="button secondary" @click="newFile">+ ไฟล์</button><button class="button secondary" @click="newFolder">+ โฟลเดอร์</button><button class="button secondary" :disabled="!selected.length" @click="download">⇩ ดาวน์โหลด</button><button class="button danger" :disabled="!selected.length" @click="confirmDelete=true">ลบ</button></div></div><div class="mt-5 rounded-2xl border border-dark-700 bg-dark-900 overflow-hidden"><div v-if="loading" class="p-10 text-center text-dark-400">กำลังโหลด…</div><div v-else-if="!entries.length" class="p-10 text-center text-dark-500">โฟลเดอร์นี้ว่างเปล่า</div><table v-else class="w-full text-sm"><thead><tr class="border-b border-dark-700 text-left text-dark-500"><th class="w-10 p-3"></th><th class="p-3">ชื่อ</th><th class="p-3 hidden sm:table-cell">แก้ไขล่าสุด</th><th class="p-3 hidden sm:table-cell">ขนาด</th><th class="p-3 w-36"></th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.name" class="border-b border-dark-800 hover:bg-dark-800/70"><td class="p-3"><input v-model="selected" :value="full(entry.name)" type="checkbox" class="accent-green-400" /></td><td class="p-3"><button class="flex items-center gap-3 text-left" @dblclick="open(entry)"><span>{{entry.type==='directory'?'📁':icon(entry.name)}}</span><span class="text-white">{{entry.name}}</span></button></td><td class="p-3 text-dark-500 hidden sm:table-cell">{{date(entry.modified)}}</td><td class="p-3 text-dark-500 hidden sm:table-cell">{{entry.type==='file'?size(entry.size):'—'}}</td><td class="p-3 whitespace-nowrap"><button v-if="entry.type==='directory'" class="text-mc-green hover:underline" @click="open(entry)">เปิด</button><button v-else-if="entry.name.toLowerCase().endsWith('.zip')" class="text-sky-300 hover:underline" @click="extract(full(entry.name))">แตก ZIP</button><button v-else class="text-mc-green hover:underline" @click="edit(full(entry.name))">แก้ไข</button><button class="ml-3 text-dark-400 hover:text-white" @click="rename(full(entry.name),entry.name)">เปลี่ยนชื่อ</button></td></tr></tbody></table></div><p v-if="error" class="mt-3 text-red-300 text-sm">{{error}}</p><div v-if="editor.open" class="fixed inset-0 z-50 bg-black/70 p-4 sm:p-10 flex"><div class="bg-dark-900 border border-dark-600 rounded-2xl w-full max-w-5xl mx-auto flex flex-col"><div class="p-4 border-b border-dark-700 flex justify-between"><b class="text-white font-mono text-sm">{{editor.path}}</b><button class="text-dark-400 hover:text-white" @click="editor.open=false">✕</button></div><textarea v-model="editor.content" class="flex-1 min-h-80 bg-[#080b0d] p-4 text-sm font-mono text-slate-200 outline-none resize-none"/><div class="p-4 border-t border-dark-700 flex justify-end gap-2"><button class="button secondary" @click="editor.open=false">ยกเลิก</button><button class="button primary" @click="saveFile">บันทึก</button></div></div></div><ConfirmDialog v-model="confirmDelete" danger title="ลบรายการที่เลือก?" :message="`จะลบ ${selected.length} รายการอย่างถาวร`" confirm-text="ลบ" @confirm="remove" /></div></template>
<script setup lang="ts">definePageMeta({layout:'server'});const route=useRoute(),id=route.params.id as string;const path=ref(''),entries=ref<any[]>([]),selected=ref<string[]>([]),loading=ref(false),error=ref(''),confirmDelete=ref(false),uploadInput=ref<HTMLInputElement>();const editor=reactive({open:false,path:'',content:''});const crumbs=computed(()=>path.value.split('/').filter(Boolean));const full=(name:string)=>path.value?[path.value,name].join('/'):name;function go(next:string){path.value=next;selected.value=[];load()}function icon(name:string){return name.endsWith('.zip')?'🗜️':'📄'}function size(bytes:number){if(!bytes)return'0 B';const units=['B','KB','MB','GB'];const i=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),3);return`${(bytes/1024**i).toFixed(i?1:0)} ${units[i]}`}function date(value:string){return value?new Date(value).toLocaleString('th-TH'):'—'}async function load(){loading.value=true;error.value='';try{entries.value=await $fetch(`/api/servers/${id}/fs`,{query:{path:path.value}})as any[]}catch(e:any){error.value=e?.data?.statusMessage||'โหลดไฟล์ไม่สำเร็จ'}finally{loading.value=false}}function open(entry:any){if(entry.type==='directory')go(full(entry.name))}async function upload(event:Event){const files=(event.target as HTMLInputElement).files;if(!files?.length)return;const form=new FormData();form.append('path',path.value);for(const file of files)form.append('files',file);try{await $fetch(`/api/servers/${id}/fs/upload`,{method:'POST',body:form});await load()}catch(e:any){error.value=e?.data?.statusMessage||'อัปโหลดไม่สำเร็จ'}finally{if(uploadInput.value)uploadInput.value.value=''}}async function newFolder(){const name=prompt('ชื่อโฟลเดอร์ใหม่');if(!name)return;try{await $fetch(`/api/servers/${id}/fs/mkdir`,{method:'POST',body:{path:full(name)}});load()}catch(e:any){error.value=e?.data?.statusMessage||'สร้างโฟลเดอร์ไม่สำเร็จ'}}function newFile(){const name=prompt('ชื่อไฟล์ใหม่ เช่น notes.txt');if(!name)return;editor.path=full(name);editor.content='';editor.open=true}async function rename(from:string,name:string){const next=prompt('ชื่อใหม่',name);if(!next||next===name)return;try{await $fetch(`/api/servers/${id}/fs/rename`,{method:'POST',body:{from,to:full(next)}});load()}catch(e:any){error.value=e?.data?.statusMessage||'เปลี่ยนชื่อไม่สำเร็จ'}}async function edit(file:string){try{const result=await $fetch(`/api/servers/${id}/fs/read`,{query:{path:file}})as any;if(typeof result.content!=='string'){error.value='ไฟล์นี้ไม่ใช่ข้อความ';return}editor.path=file;editor.content=result.content;editor.open=true}catch(e:any){error.value=e?.data?.statusMessage||'เปิดไฟล์ไม่สำเร็จ'}}async function saveFile(){try{await $fetch(`/api/servers/${id}/fs/write`,{method:'PUT',body:{path:editor.path,content:editor.content}});editor.open=false;load()}catch(e:any){error.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}}async function extract(file:string){try{await $fetch(`/api/servers/${id}/fs/extract`,{method:'POST',body:{path:file,dest:path.value}});await load()}catch(e:any){error.value=e?.data?.statusMessage||'แตก ZIP ไม่สำเร็จ'}}async function remove(){try{await $fetch(`/api/servers/${id}/fs/delete`,{method:'DELETE',body:{paths:selected.value}});selected.value=[];load()}catch(e:any){error.value=e?.data?.statusMessage||'ลบไม่สำเร็จ'}}function download(){const query=selected.value.map(p=>`paths=${encodeURIComponent(p)}`).join('&');window.open(`/api/servers/${id}/fs/download?${query}`,'_blank')}onMounted(load)</script><style scoped>.button{@apply rounded-xl px-3 py-2 text-sm font-medium transition-colors disabled:opacity-40}.primary{@apply bg-mc-green hover:bg-green-300 text-dark-950}.secondary{@apply bg-dark-700 hover:bg-dark-600 text-dark-100}.danger{@apply bg-red-800 hover:bg-red-700 text-white}</style>
